  version: parseVersion(process.env.MC_VERSION),
  auth: process.env.MC_AUTH || 'offline',
  password: process.env.MC_PASSWORD || '',
  autoLogin: process.env.AUTO_LOGIN !== 'false',
  autoReconnect: process.env.AUTO_RECONNECT !== 'false',
