  });

  bot.on('end', () => {
    log('Ulanish uzildi.');
    if (farmInterval) {
        clearInterval(farmInterval);
        farmInterval = null;
    }
    isWorking = false;
    scheduleReconnect();
  });
}

function loginIfNeeded() {
  if (!config.autoLogin || !config.password) return;
  setTimeout(() => {
    if (bot && bot.entity) {
        bot.chat(`/register ${config.password} ${config.password}`);
    }
  }, 1500);
  setTimeout(() => {
    if (bot && bot.entity) {
