    const hasCocoaBeans = bot.inventory.items().some(item => item.type === cocoaItemId);

    if (!hasCocoaBeans) {
      log("Inventarda ekish uchun cocoa beans qolmadi.");
      isWorking = false;
      return;
    }

    // Cocoa beans ni qo'lga olish
    await bot.equip(cocoaItemId, 'hand');

