                    await chest.deposit(item.type, null, item.count).catch(() => {});
                } else if (kept + item.count > 64) {
                    // Agar bu stakdan faqat bir qismi zaxira uchun kerak bo'lsa
                    const toDeposit = item.count - (64 - kept);
