      if (block && block.getProperties() && Number(block.getProperties().age) === 2) {
        targetPos = pos;
        targetBlock = block;
        break; // Eng yaqin pishganini topdik
      }
    }

    if (!targetBlock) return; // Hozircha pishgan hosil yo'q

