    log(`Xato: ${error.message}`);
  });

  bot.on('end', () => {
    log('Ulanish uzildi.');
    if (farmInterval) {
        clearInterval(farmInterval);
        farmInterval = null;
    }
    isWorking = false;
    scheduleReconnect();
  });
