        if (!targetChestBlock) {
            const currentBlock = bot.blockAt(chestPos);
            log(`Belgilangan kordinatada sandiq topilmadi! Siz yozgan kordinatada aslida: ${currentBlock ? currentBlock.name : "bo'shliq (air)"} joylashgan.`);
