        // Inventardagi barcha cocoa beanlarni tekshiramiz
        for (const item of bot.inventory.items()) {
            if (item.type === cocoaItemId) {
                if (kept >= 64) {
                    // Agar 64 ta zaxira yig'ilgan bo'lsa, qolganini to'liq solamiz
