        log("Hosil sandiqqa joylandi, ish davom etmoqda.");
        isWorking = false;
        return; // Keyingi loopgacha kutamiz
    }

    const cocoaId = bot.registry.blocksByName.cocoa?.id;
    if (!cocoaId) return;

    // Atrofdagi barcha cocoa bloklarini qidiramiz (radius: 30)
