    const axes = ['netherite_axe', 'diamond_axe', 'golden_axe', 'iron_axe', 'stone_axe', 'wooden_axe'];
    for (const axeName of axes) {
      const axeItem = bot.inventory.items().find(item => item.name === axeName);
      if (axeItem) {
        await bot.equip(axeItem, 'hand');
