        log('====================================================');
        config.autoReconnect = false; // Spam qilib bloklanmaslik uchun ulanishni to'xtatamiz
    }
  });

  bot.on('error', error => {
    log(`Xato: ${error.message}`);
  });

  bot.on('end', () => {
    log('Ulanish uzildi.');
    if (farmInterval) {
        clearInterval(farmInterval);
        farmInterval = null;
    }
    isWorking = false;
    scheduleReconnect();
  });
}

